import json,numpy as np

def load(tag):
 m=json.load(open(f'/app/runs/{tag}/meta.json')); c=m['cameras']['robot_r1:left_realsense_link:Camera:0'];return np.array(c['intrinsic_cv']),np.array(c['extrinsic_cv'])
K0,E0=load('tuck_to_high_safe_pose'); K1,E1=load('pregrasp_orange_can1')
def floorpoint(K,E,uv):
 R=E[:3,:3];t=E[:3,3];C=-R.T@t;d=R.T@np.linalg.inv(K)@np.array([*uv,1]);return C+(-C[2]/d[2])*d
def project(K,E,P):
 p=E[:3,:3]@P+E[:3,3]; uv=K@p; return uv[:2]/uv[2]
for uv in [(80,75),(80,77),(80,78),(81,76),(82,77),(82,60)]:
 P=floorpoint(K0,E0,uv); print(uv,P,'newpix',project(K1,E1,P))
for uv in [(181,54),(185,55),(190,56),(180,57),(178,50)]:
 P=floorpoint(K1,E1,uv); print('new',uv,P,'oldpix',project(K0,E0,P))
